/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Everything that isn't closed; what `status=open` expands to. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

/** The two status groups the filter vocabulary accepts alongside literal statuses. */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: readonly IssueStatusGroup[] = ["open", "closed"];

/**
 * A single `status=` token, which is either a literal status or one of the
 * groups above, expanded to the statuses it stands for. Unknown tokens expand
 * to nothing, which is how the codec and the schema both drop them.
 */
export function expandIssueStatusToken(token: string): readonly IssueStatus[] {
  if (token === "open") return OPEN_ISSUE_STATUSES;
  if (token === "closed") return CLOSED_ISSUE_STATUSES;
  return (ISSUE_STATUSES as readonly string[]).includes(token)
    ? [token as IssueStatus]
    : [];
}

/** Expands every token in a `status=` list, de-duplicating the result. */
export function expandIssueStatusTokens(
  tokens: readonly string[],
): readonly IssueStatus[] {
  const seen = new Set<IssueStatus>();
  for (const token of tokens) {
    for (const status of expandIssueStatusToken(token)) seen.add(status);
  }
  return [...seen];
}

const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

export function isCalendarDate(value: string): boolean {
  return CALENDAR_DATE.test(value);
}

/**
 * `due_before` always resolves to a strict "less than" cutoff: a full
 * timestamp is used as-is, while a calendar date is read in UTC and widened
 * to the instant right after that whole day, so the day itself is included.
 */
export function dueBeforeCutoff(value: string): IsoTimestamp {
  if (!isCalendarDate(value)) return value as IsoTimestamp;
  const next = new Date(`${value}T00:00:00.000Z`);
  next.setUTCDate(next.getUTCDate() + 1);
  return next.toISOString() as IsoTimestamp;
}

