export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(resolveSelfFilters(actor, input));
}

/**
 * `assigneeId` / `authorId` of `"me"` is resolved here, against the acting
 * user, so a page and an API caller filtering on `"me"` get the same answer.
 */
function resolveSelfFilters(
  actor: Actor,
  input: IssueFilterInput,
): IssueFilterInput {
  return {
    ...input,
    ...(input.assigneeId === "me" ? { assigneeId: actor.userId } : {}),
    ...(input.authorId === "me" ? { authorId: actor.userId } : {}),
  };
}

