    const { assigneeId: _assigneeId, ...rest } = filter;
    return rest;
  }
  return {
    ...filter,
    assigneeId: raw === UNASSIGNED_TOKEN ? null : (raw as UserId),
  };
}

const ARCHIVED_OPTIONS: readonly SelectOption[] = [
  { value: "live", label: "Live issues" },
  { value: "include", label: "Include archived" },
  { value: "only", label: "Archived only" },
];

function withArchivedScope(filter: IssueFilter, raw: string): IssueFilter {
  const { includeArchived: _include, archivedOnly: _only, ...rest } = filter;
  if (raw === "include") return { ...rest, includeArchived: true };
